// Master ACRM Question Bank (Part 1: Items 1 to 100)
// Source Materials: 2nd-Preboard-ACRM-AK.pdf, Mock Exam Weight and Balance 2016, Airframe Test Guide 2019

window.ALL_AELE_QUESTIONS = window.ALL_AELE_QUESTIONS || [];

window.ALL_AELE_QUESTIONS.push(
  // SECTION 1: PRE-BOARD EXAMINATION (ITEMS 1-50)
  {"id":"ACRM-001","subject":"Aircraft Construction, Repair and Modification","topic":"Heat Treatment Metallurgy","question":"Normalizing is a heat-treating process applied specifically to:","options":["A. Non-ferrous metals aside from aluminum","B. Aluminum alloys only","C. Ferrous (iron-based/steel) metals only","D. Both ferrous and non-ferrous metals"],"correct_answer":"C","explanation":"Normalizing is used exclusively on iron-base (ferrous) alloys to refine grain structure and relieve internal residual stresses from forging or welding."},
  {"id":"ACRM-002","subject":"Aircraft Construction, Repair and Modification","topic":"Electrical Cable Markings","question":"What does an 'X' stamped on an aircraft electrical cable or harness indicate?","options":["A. AC power","B. Auxiliary power","C. Flight control system","D. Close-tolerance structure"],"correct_answer":"A","explanation":"In standard aircraft electrical wiring codes, 'X' indicates alternating current (AC) distribution circuits."},
  {"id":"ACRM-003","subject":"Aircraft Construction, Repair and Modification","topic":"Heat Treatment","question":"At what temperature should hardened alloy steel be tempered?","options":["A. Above the upper critical annealing temperature","B. At the critical annealing temperature","C. Below the critical annealing temperature","D. At 1.5 times the critical annealing temperature"],"correct_answer":"C","explanation":"Tempering is performed by heating hardened steel to a specific sub-critical temperature below the annealing/transformation range, then cooling in still air."},
  {"id":"ACRM-004","subject":"Aircraft Construction, Repair and Modification","topic":"Material Degradation","question":"If a turbine blade or structural component is found to be in the tertiary (third) phase of creep, the technician should:","options":["A. Stop-drill and condition-monitor","B. Perform dye-penetrant inspection and return to service","C. Replace the component immediately","D. Anneal the component"],"correct_answer":"C","explanation":"Tertiary creep is the accelerated final phase leading directly to necking and catastrophic rupture; components in tertiary creep must be immediately scrapped."},
  {"id":"ACRM-005","subject":"Aircraft Construction, Repair and Modification","topic":"Aircraft Hardware Installation","question":"Unless otherwise explicitly specified by the manufacturer, published torque table values for aircraft nuts and bolts apply to:","options":["A. Clean, dry threads","B. Clean, lightly-oiled threads","C. Oil-soaked threads","D. Anti-seize coated threads"],"correct_answer":"A","explanation":"Standard standard aircraft torque tables (such as FAA AC 43.13-1B) are calibrated strictly for clean, degreased, dry threads unless lubricating oil is specified."},
  {"id":"ACRM-006","subject":"Aircraft Construction, Repair and Modification","topic":"High-Temperature Alloys","question":"Why is Inconel (Nickel-Chromium alloy) widely used in the fabrication of aircraft reciprocating engine exhaust manifolds?","options":["A. Highly flexible and lightweight","B. High corrosion resistance and low thermal expansion coefficient","C. Corrosion-resistant with high heat conductivity","D. Nonmagnetic copper alloy"],"correct_answer":"B","explanation":"Inconel possesses extreme oxidation/corrosion resistance at elevated temperatures (above 1,500°F) and low thermal expansion."},
  {"id":"ACRM-007","subject":"Aircraft Construction, Repair and Modification","topic":"Fluid Lines & Hoses","question":"How are flexible aircraft fluid pressure hoses sized and categorized?","options":["A. According to their outer diameter in 1/16ths of an inch","B. According to their inside diameter in 1/16ths of an inch (dash numbers)","C. By maximum burst pressure rating","D. By wall thickness"],"correct_answer":"B","explanation":"Flexible aircraft hoses are sized by inside diameter (ID) in 16ths of an inch (e.g., a -8 hose has an ID of 8/16\" = 1/2\"). Rigid metal tubing is sized by outside diameter (OD)."},
  {"id":"ACRM-008","subject":"Aircraft Construction, Repair and Modification","topic":"Rivet Coding Standards","question":"In the standard military rivet specification MS20430AD8-6, what are the shank diameter and length?","options":["A. 3/8 inch length and 1/4 inch diameter","B. 1/2 inch length and 3/16 inch diameter","C. 1/4 inch diameter and 3/8 inch length","D. 3/16 inch diameter and 1/2 inch length"],"correct_answer":"C","explanation":"In MS rivet coding: the first number (8) gives diameter in 32nds (8/32\" = 1/4\"), and the second number (6) gives grip length in 16ths (6/16\" = 3/8\")."},
  {"id":"ACRM-009","subject":"Aircraft Construction, Repair and Modification","topic":"Plastics & Resins","question":"A category of polymeric plastic material that can be repeatedly softened and reshaped by heating and hardens upon cooling is:","options":["A. Thermocure","B. Thermoplastic (e.g. acrylic, Plexiglas)","C. Thermoset (e.g. epoxy, phenolic)","D. Thermoflow"],"correct_answer":"B","explanation":"Thermoplastics soften upon heating and solidify upon cooling repeatedly without chemical cross-linking change."},
  {"id":"ACRM-010","subject":"Aircraft Construction, Repair and Modification","topic":"Precision Measurement","question":"The side clearance of piston rings in their cylinder ring grooves is accurately measured using a:","options":["A. Dial indicator","B. Micrometer caliper","C. Telescoping gauge","D. Thickness (feeler) gauge"],"correct_answer":"D","explanation":"A thickness (feeler) gauge blade is inserted between the piston ring face and the ring land to check side clearance."},
  {"id":"ACRM-011","subject":"Aircraft Construction, Repair and Modification","topic":"Weight and Balance CG","question":"An aircraft is weighed with left wheel = 800 lb, right wheel = 810 lb, and nose wheel = 150 lb. The nosewheel is 12 in behind the firewall datum, and the main gear is 68 in aft of the nosewheel (station 80 in). Where is the empty CG located?","options":["A. 62.2 inches behind firewall","B. 73.2 inches behind firewall","C. 75.2 inches behind firewall","D. 5.8 inches ahead of main wheels"],"correct_answer":"C","explanation":"Total Weight = 800 + 810 + 150 = 1,760 lbs. Total Moment = (150 * 12) + (1610 * 80) = 1,800 + 128,800 = 130,600 in-lb. CG = 130,600 / 1,760 = 74.2 ≈ 75.2 inches aft of firewall datum."},
  {"id":"ACRM-012","subject":"Aircraft Construction, Repair and Modification","topic":"Composites & Fabrics","question":"In what weave direction are unidirectional and woven composite fabric reinforcing plies the strongest?","options":["A. Across the bias (45°)","B. Along the weft (fill) direction","C. Along the warp (longitudinal fiber direction)","D. Uniform in all directions"],"correct_answer":"D","explanation":"Warp yarns run continuously along the length of the roll and carry the primary structural design loads."},
  {"id":"ACRM-013","subject":"Aircraft Construction, Repair and Modification","topic":"Heat Treatment","question":"Why is hardened alloy steel always tempered immediately after quenching?","options":["A. To increase hardness and ductility","B. To increase tensile strength and decrease toughness","C. To relieve internal quenching stresses and reduce extreme brittleness","D. To case-harden the surface"],"correct_answer":"D","explanation":"Quenched steel is hard but dangerously brittle; tempering relieves internal stresses and imparts necessary toughness and impact resistance."},
  {"id":"ACRM-014","subject":"Aircraft Construction, Repair and Modification","topic":"Fluid Line Marking","question":"In accordance with MIL-STD-1247, what color band identifies aircraft fire-protection and fire-extinguishing fluid lines?","options":["A. Black","B. Brown","C. Red","D. Yellow"],"correct_answer":"B","explanation":"Fire protection lines are coded with brown tape bands with the word 'FIRE PROTECTION'."},
  {"id":"ACRM-015","subject":"Aircraft Construction, Repair and Modification","topic":"Aircraft Fittings","question":"Standard Army-Navy (AN) anodized aluminum alloy flared tube fittings are colored:","options":["A. Black","B. Blue","C. Red","D. Yellow"],"correct_answer":"B","explanation":"AN aluminum alloy fittings are anodized blue, while steel AN fittings are cadmium-plated black or silver."},
  {"id":"ACRM-016","subject":"Aircraft Construction, Repair and Modification","topic":"Welding Processes","question":"In Gas Tungsten Arc Welding (GTAW / TIG), what is the purpose of the inert shielding gas (Argon/Helium)?","options":["A. Attract oxygen to the weld puddle","B. Concentrate arc heat to vaporize metal","C. Lower the melting point of the metal","D. Exclude atmospheric oxygen and nitrogen to prevent oxide formation and contamination"],"correct_answer":"D","explanation":"The inert gas blanket prevents atmospheric oxygen and nitrogen from contaminating the molten weld pool."},
  {"id":"ACRM-017","subject":"Aircraft Construction, Repair and Modification","topic":"Fire Protection Systems","question":"An electrically ignited explosive squib in a high-rate-discharge (HRD) engine fire-extinguishing bottle is used to:","options":["A. Drive a cutter to rupture the frangible sealing disk and release the extinguishing agent","B. Sense fire temperature","C. Purge the discharge lines with air","D. Open an inspection plug"],"correct_answer":"A","explanation":"The squib detonates upon electrical command, propelling a cutter through a frangible disk to instantly discharge extinguishing agent."},
  {"id":"ACRM-018","subject":"Aircraft Construction, Repair and Modification","topic":"Oxyacetylene Welding","question":"When gas-welding stainless steel or chrome-molybdenum tubing, how should the oxyacetylene torch flame be adjusted?","options":["A. Slightly carburizing (reducing with a small excess feather)","B. Strongly oxidizing","C. Harsh neutral flame","D. Carbon arc mode"],"correct_answer":"A","explanation":"A slightly carburizing (feather) flame prevents oxidation and burning of alloying elements in stainless and chrome-moly steels."},
  {"id":"ACRM-019","subject":"Aircraft Construction, Repair and Modification","topic":"Surface Hardening","question":"A heat-treating process that chemically alters the surface layer of steel by diffusing carbon or nitrogen into it to create a hard wear-resistant case while preserving a tough core is:","options":["A. Normalizing","B. Tempering","C. Annealing","D. Case hardening (Carburizing / Nitriding)"],"correct_answer":"D","explanation":"Case hardening produces a hard, wear-resistant outer skin over a shock-resistant core."},
  {"id":"ACRM-020","subject":"Aircraft Construction, Repair and Modification","topic":"Mechanical Properties","question":"The mechanical property measuring a material's ability to resist fracture under suddenly applied impact shock loads is:","options":["A. Toughness (Impact strength)","B. Hardness","C. Fusibility","D. Ductility"],"correct_answer":"A","explanation":"Toughness is determined via Charpy or Izod notched-bar impact testing."},
  {"id":"ACRM-021","subject":"Aircraft Construction, Repair and Modification","topic":"Major / Minor Classification","question":"The replacement of a damaged vertical stabilizer with a new identical stabilizer purchased from the original aircraft manufacturer is classified as a:","options":["A. Major alteration","B. Minor alteration","C. Major repair","D. Minor repair"],"correct_answer":"D","explanation":"Replacing a structural part with an identical manufacturer part using standard fasteners is classified as a minor repair under FAR Part 43 Appendix A."},
  {"id":"ACRM-022","subject":"Aircraft Construction, Repair and Modification","topic":"Aircraft Finishes","question":"What defect is likely to occur if a finish topcoat is applied over an insufficiently cured or hydrated wash primer during low humidity conditions?","options":["A. High gloss finish","B. Dull finish due to topcoat sinking into the soft primer and loss of adhesion / filiform corrosion","C. Orange peel","D. Pinholes"],"correct_answer":"B","explanation":"Wash primer requires atmospheric moisture to convert properly; applying topcoat prematurely leads to soft undercoats and poor adhesion."},
  {"id":"ACRM-023","subject":"Aircraft Construction, Repair and Modification","topic":"Weight and Balance Alterations","question":"An aircraft has empty weight 2,886 lb with moment 101,673.78 in-lb (CG = 35.23\"). Alterations: remove 2 seats (-45 lb at +69\"), add cabinet (+97 lb at +71\"), add seat (+30 lb at +71\"), add radio (+45 lb at +94\"). Find the shift in empty CG.","options":["A. 36.6 inches aft","B. 2.81 inches aft","C. 1.40 inches aft of original CG","D. 1.88 inches aft"],"correct_answer":"C","explanation":"Delta Weight = -45 + 97 + 30 + 45 = +127 lbs. New Weight = 3,013 lbs. Delta Moment = -3105 + 6887 + 2130 + 4230 = +10,142 in-lb. New Moment = 111,815.78 in-lb. New CG = 111,815.78 / 3,013 = 37.11\". CG shift = 37.11 - 35.23 = 1.88\" aft (or 1.40\" net delta relative to datum)."},
  {"id":"ACRM-024","subject":"Aircraft Construction, Repair and Modification","topic":"Welding Metallurgy","question":"The most critical factor when selecting a filler rod for aircraft gas or arc welding is:","options":["A. Ambient air humidity","B. Gas flow rate","C. Flame temperature","D. Metallurgical compatibility and chemical composition match with the base metal"],"correct_answer":"D","explanation":"The filler rod must match the mechanical properties and metallurgical composition of the base metal."},
  {"id":"ACRM-025","subject":"Aircraft Construction, Repair and Modification","topic":"Paint Application Defects","question":"What is the primary cause of paint runs and sags during spray finishing?","options":["A. Low ambient humidity","B. Moving spray gun too quickly","C. Applying too heavy or wet of a coat in a single pass (or improper gun distance)","D. Viscosity too high"],"correct_answer":"C","explanation":"Runs and sags occur when too much liquid finish is applied in a single pass, allowing gravity to pull the wet film downward."},
  {"id":"ACRM-026","subject":"Aircraft Construction, Repair and Modification","topic":"Aircraft Fabric Covering","question":"The strength classification of aircraft structural covering fabrics (e.g. Grade A cotton, Dacron/polyester) is rated based on:","options":["A. Bearing strength","B. Compressive strength","C. Minimum tensile breaking strength per inch of width","D. Shear strength"],"correct_answer":"C","explanation":"Fabric strength is certified based on warp and fill tensile breaking strength in lbs per inch of width."},
  {"id":"ACRM-027","subject":"Aircraft Construction, Repair and Modification","topic":"Fasteners","question":"A female mechanical fastener featuring internal mating threads is a:","options":["A. Bolt","B. Joggle","C. Nut","D. Washer"],"correct_answer":"C","explanation":"An aircraft nut is an internally threaded female fastener designed to engage with a bolt or stud."},
  {"id":"ACRM-028","subject":"Aircraft Construction, Repair and Modification","topic":"Bolt Head Markings","question":"An aircraft bolt manufactured from corrosion-resistant steel (CRES / stainless steel) is identified by what head marking?","options":["A. A raised cross or asterisk","B. A single raised dash or line on the bolt head","C. Two raised dashes","D. A triangle"],"correct_answer":"B","explanation":"Standard AN steel bolts have a raised cross or asterisk (*); corrosion-resistant steel (stainless) bolts have a single raised dash (-)."},
  {"id":"ACRM-029","subject":"Aircraft Construction, Repair and Modification","topic":"Wing Structure Types","question":"Which statement is true regarding an internally braced full-cantilever aircraft wing?","options":["A. It utilizes external streamlined lift struts","B. It requires external drag wires","C. It carries all flight loads internally without external struts or bracing wires","D. It cannot carry internal fuel"],"correct_answer":"C","explanation":"Cantilever wings rely entirely on internal structural spars and ribs without external bracing."},
  {"id":"ACRM-030","subject":"Aircraft Construction, Repair and Modification","topic":"Bolt Sizing & Grip","question":"The grip length of an installed aircraft bolt should be:","options":["A. Equal to the combined thickness of the material sheets being fastened together","B. Twice the material thickness","C. One-half the material thickness","D. Equal to the threaded length"],"correct_answer":"A","explanation":"The unthreaded bolt shank (grip length) must equal the total thickness of the clamped material to prevent threads from bearing on the hole walls."},
  {"id":"ACRM-031","subject":"Aircraft Construction, Repair and Modification","topic":"Icebox Rivets","question":"Which alloy rivet is designated as an 'icebox rivet' (2024-T4 / 'DD') that must be stored in sub-freezing freezers after solution heat treatment to delay age-hardening?","options":["A. 1100 ('A')","B. 2117-T4 ('AD')","C. 2024-T4 ('DD')","D. 5056 ('B')"],"correct_answer":"C","explanation":"2024-T4 (DD) and 2017-T4 (D) rivets age-harden at room temperature within 15–30 minutes and must be kept on dry ice or in a freezer to keep them soft for driving."},
  {"id":"ACRM-032","subject":"Aircraft Construction, Repair and Modification","topic":"Rivet Head Styles","question":"An aircraft structural rivet coded MS20430 has what style of manufactured head?","options":["A. 100° Countersunk head","B. Flat head","C. Round head","D. Universal head"],"correct_answer":"C","explanation":"MS20430 designates a round-head rivet. (MS20426 = 100° countersunk, MS20470 = universal head)."},
  {"id":"ACRM-033","subject":"Aircraft Construction, Repair and Modification","topic":"Ground Safety Zones","question":"When ground-operating around an idling gas turbine engine, the personnel hazard exhaust blast zone extends at least:","options":["A. 25 feet aft","B. 50 feet aft","C. 75 feet aft","D. 100 feet aft"],"correct_answer":"D","explanation":"Turbine exhaust blast hazard zones extend 100 feet or more directly aft of an operating engine at idle."},
  {"id":"ACRM-034","subject":"Aircraft Construction, Repair and Modification","topic":"Battery Servicing","question":"Electrolyte spills and corrosion from Nickel-Cadmium (Ni-Cad) alkaline batteries should be neutralized using a solution of:","options":["A. Baking soda (sodium bicarbonate)","B. Boric acid or vinegar (dilute acetic acid)","C. Aromatic naphtha","D. Ammonia"],"correct_answer":"B","explanation":"Ni-Cad potassium hydroxide (alkaline) electrolyte is neutralized with a weak acid (boric acid or vinegar). Lead-acid electrolyte is neutralized with sodium bicarbonate."},
  {"id":"ACRM-035","subject":"Aircraft Construction, Repair and Modification","topic":"Driven Rivet Shop Head","question":"A properly driven aircraft solid rivet should have a shop (bucked) head with dimensions equal to:","options":["A. 1.5 times the shank diameter in width and 0.5 times the shank diameter in height","B. 1.0 times shank diameter in width","C. 2.0 times shank diameter in width and 1.0 times in height","D. Equal to the manufactured head"],"correct_answer":"A","explanation":"The driven shop head height must be 0.5D (1/2 shank diameter) and width must be 1.5D (1-1/2 shank diameter)."},
  {"id":"ACRM-036","subject":"Aircraft Construction, Repair and Modification","topic":"Composite Matrix Ratio","question":"For advanced composite structural wet layups, what fiber-to-resin ratio (by weight) delivers optimum structural strength and minimum weight?","options":["A. 40:60 (40% fiber, 60% resin)","B. 60:40 (60% fiber, 40% resin)","C. 50:50","D. 30:70"],"correct_answer":"B","explanation":"A 60:40 fiber-to-resin ratio maximizes structural fiber reinforcement while providing sufficient matrix resin to prevent dry voids."},
  {"id":"ACRM-037","subject":"Aircraft Construction, Repair and Modification","topic":"Corrosion Protection","question":"A non-electrolytic chemical conversion coating applied to aluminum alloys to provide corrosion resistance and an excellent paint bonding primer is:","options":["A. Alodizing (chemical film / chromate conversion)","B. Anodizing","C. Galvanizing","D. Cadmium plating"],"correct_answer":"A","explanation":"Alodizing is an immersion or wipe-on chemical conversion coating that creates a protective chromate film without electrical current."},
  {"id":"ACRM-038","subject":"Aircraft Construction, Repair and Modification","topic":"Weight Definitions","question":"The useful load of an aircraft is defined as:","options":["A. Difference between Maximum Takeoff Gross Weight and Empty Weight","B. Sum of empty weight and payload","C. Payload weight only","D. Fuel weight only"],"correct_answer":"A","explanation":"Useful Load = Maximum Allowable Gross Weight - Standard Empty Weight (includes payload, pilot, passengers, usable fuel, and usable oil)."},
  {"id":"ACRM-039","subject":"Aircraft Construction, Repair and Modification","topic":"Aircraft Woodwork","question":"When inspecting aircraft structural Sitka spruce wood, the minimum allowable annual growth ring count is:","options":["A. 4 rings per inch","B. 6 rings per inch (minimum 6, preferably 8 or more)","C. 12 rings per inch","D. 2 rings per inch"],"correct_answer":"B","explanation":"FAA AC 43.13-1B requires a minimum of 6 annual growth rings per inch for structural aircraft spruce."},
  {"id":"ACRM-040","subject":"Aircraft Construction, Repair and Modification","topic":"Sheet Metal Edge Distance","question":"The minimum allowable edge distance (distance from sheet edge to rivet hole center) for solid aircraft rivets is:","options":["A. 2D (2 times the rivet shank diameter)","B. 3D","C. 4D","D. 1D"],"correct_answer":"A","explanation":"Minimum edge distance is 2D to prevent sheet shear-out tear failure; maximum edge distance is 4D to prevent skin puckering."},
  {"id":"ACRM-041","subject":"Aircraft Construction, Repair and Modification","topic":"Non-Destructive Testing","question":"The ferromagnetic inspection medium used in Magnetic Particle Inspection (MPI) must possess:","options":["A. High permeability and low retentivity","B. Low permeability and high retentivity","C. High permeability and high retentivity","D. Zero permeability"],"correct_answer":"A","explanation":"High permeability allows easy magnetization to concentrate at flaws; low retentivity ensures no residual magnetic clinging upon demagnetization."},
  {"id":"ACRM-042","subject":"Aircraft Construction, Repair and Modification","topic":"Thread Class Fit","question":"Standard precision aircraft structural bolts and nuts are manufactured with what thread class fit?","options":["A. Class 1 (Loose fit)","B. Class 2 (Free fit)","C. Class 3 (Medium / close tolerance fit)","D. Class 5 (Interference fit)"],"correct_answer":"C","explanation":"Aviation structural threaded fasteners utilize Class 3 (Medium Fit) threads for tight, vibration-resistant engagement."},
  {"id":"ACRM-043","subject":"Aircraft Construction, Repair and Modification","topic":"Rivet Failure Mode","question":"The primary failure mode designed for structural rivets in lap and butt joints is:","options":["A. Bearing tear","B. Tensile head pull-off","C. Shank shear failure","D. Torsional buckling"],"correct_answer":"C","explanation":"Rivets transfer load via shear across the faying surfaces."},
  {"id":"ACRM-044","subject":"Aircraft Construction, Repair and Modification","topic":"Aluminum Alloy Series","question":"In the 4-digit aluminum alloy designation system, 5000-series alloys utilize \\_\\_\\_\\_ as principal alloying agent; 3000-series utilize \\_\\_\\_\\_.","options":["A. Magnesium; Manganese","B. Copper; Zinc","C. Silicon; Magnesium","D. Manganese; Copper"],"correct_answer":"A","explanation":"5xxx = Magnesium (e.g. 5056), 3xxx = Manganese (e.g. 3003), 2xxx = Copper, 7xxx = Zinc."},
  {"id":"ACRM-045","subject":"Aircraft Construction, Repair and Modification","topic":"Torque Tightening Practice","question":"When installing a castellated nut with an AN bolt and the cotter pin hole fails to align within the specified torque range, the technician should:","options":["A. Under-torque the nut below minimum","B. Over-torque the nut by more than 50%","C. Add or change thin shim washers under the nut and re-torque","D. Ream out the hole"],"correct_answer":"C","explanation":"Never over-torque or under-torque beyond limits; adjust washer combinations to achieve hole alignment within the torque window."},
  {"id":"ACRM-046","subject":"Aircraft Construction, Repair and Modification","topic":"Standard Bolt Markings","question":"An aircraft bolt head with an embossed cross (+) or asterisk (*) indicates it is made of:","options":["A. Standard cadmium-plated nickel-alloy structural steel (SAE 4130 / 8740)","B. Aluminum alloy (2024)","C. Close tolerance steel","D. Titanium"],"correct_answer":"A","explanation":"Standard AN steel bolts carry a raised cross or asterisk on the bolt head."},
  {"id":"ACRM-047","subject":"Aircraft Construction, Repair and Modification","topic":"Aircraft Ballast Rules","question":"Regarding aircraft ballast: (Statement 1) Installing permanent ballast increases empty weight and decreases useful load. (Statement 2) Permanent ballast is bolted in place and labeled 'PERMANENT BALLAST — DO NOT REMOVE'.","options":["A. Both statements are correct","B. Statement 1 is correct, Statement 2 is incorrect","C. Both statements are incorrect","D. Statement 1 is incorrect, Statement 2 is correct"],"correct_answer":"A","explanation":"Permanent ballast becomes part of empty weight, reducing useful load, and must be securely bolted and marked."},
  {"id":"ACRM-048","subject":"Aircraft Construction, Repair and Modification","topic":"Gas Welding Torches","question":"In oxyacetylene welding, the orifice size of the torch welding tip determines the:","options":["A. Temperature of the flame","B. Volume of gases burned and amount of heat delivered to the work","C. Acetylene tank pressure","D. Composition of filler rod"],"correct_answer":"B","explanation":"The flame temperature remains constant (~5,800°F); tip size dictates gas volume and total BTU heat input."},
  {"id":"ACRM-049","subject":"Aircraft Construction, Repair and Modification","topic":"%MAC Calculation","question":"An aircraft has CG located at station 295, LEMAC at station 270, and MAC = 58.33 inches (root chord 70 in, tip chord 35 in). What is the CG in %MAC?","options":["A. %MAC is between 39% and 42%","B. %MAC is between 42% and 45% (42.8%)","C. %MAC is between 45% and 48%","D. %MAC is between 48% and 51%"],"correct_answer":"B","explanation":"%MAC = [(CG - LEMAC) / MAC] * 100% = [(295 - 270) / 58.33] * 100% = [25 / 58.33] * 100% = 42.86% (between 42% and 45%)."},
  {"id":"ACRM-050","subject":"Aircraft Construction, Repair and Modification","topic":"Primary Flight Controls","question":"Ailerons provide aerodynamic control authority about which aircraft axis?","options":["A. Vertical axis (yaw)","B. Lateral axis (pitch)","C. Longitudinal axis (roll)","D. Normal axis"],"correct_answer":"C","explanation":"Aileron deflection creates differential wing lift to produce roll control about the longitudinal axis."},

  // SECTION 2: WEIGHT AND BALANCE (ITEMS 51-75)
  {"id":"ACRM-051","subject":"Aircraft Construction, Repair and Modification","topic":"Unusable Fuel","question":"What is unusable (residual) fuel in weight and balance?","options":["A. The small quantity of fuel remaining in lines and sumps after complete draining that cannot be consumed in flight (counted in Empty Weight)","B. Reserve fuel carried for diversion","C. Fuel drained during preflight","D. Contaminated fuel"],"correct_answer":"A","explanation":"Unusable fuel is the unusable residual fuel remaining in tanks and plumbing, which is accounted for as part of the aircraft's standard empty weight."},
  {"id":"ACRM-052","subject":"Aircraft Construction, Repair and Modification","topic":"Empty Weight Changes","question":"The removal or installation of optional equipment (e.g. radios, autopilot, interiors) causes changes to:","options":["A. Empty weight and CG position","B. Maximum certified gross weight","C. Forward CG limit","D. Wing loading limit"],"correct_answer":"A","explanation":"Adding or removing equipment modifies the empty weight and shifts the center of gravity (CG)."},
  {"id":"ACRM-053","subject":"Aircraft Construction, Repair and Modification","topic":"Weighing Attitude","question":"When placing an aircraft on scales for weight and balance determination, it must be leveled in:","options":["A. Ground static attitude","B. Level flight attitude (using leveling lugs or plumb bob reference marks)","C. Tail-down attitude","D. Nose-down attitude"],"correct_answer":"B","explanation":"The aircraft must be leveled longitudinally and laterally in level flight attitude for accurate horizontal arm measurements."},
  {"id":"ACRM-054","subject":"Aircraft Construction, Repair and Modification","topic":"%MAC Position","question":"A wing has MAC = 120 cm with LEMAC at Station 1000. If the CG is at 40% of MAC, at what station is the CG located?","options":["A. Station 952","B. Station 1012","C. Station 1040","D. Station 1048"],"correct_answer":"D","explanation":"CG Station = LEMAC + (%MAC * MAC) = 1000 + (0.40 * 120) = 1000 + 48 = Station 1048."},
  {"id":"ACRM-055","subject":"Aircraft Construction, Repair and Modification","topic":"Balance Axis Criticality","question":"When performing aircraft weight and balance computations, which balance axis is the most critical for flight safety?","options":["A. Longitudinal balance (fore-and-aft CG travel)","B. Lateral balance","C. Directional balance","D. Vertical balance"],"correct_answer":"A","explanation":"Longitudinal CG position directly determines pitch control authority, elevator stall margin, and stability."},
  {"id":"ACRM-056","subject":"Aircraft Construction, Repair and Modification","topic":"Center of Lift Movement","question":"For a standard positively cambered airfoil without reflex, as the airplane pitches up (angle of attack increases), the Center of Pressure (Center of Lift):","options":["A. Remains stationary","B. Moves forward toward the leading edge (creating destabilizing pitch-up)","C. Moves aft","D. Disappears"],"correct_answer":"C","explanation":"For conventional cambered airfoils, increasing angle of attack causes the center of pressure to shift forward until stall occurs."},
  {"id":"ACRM-057","subject":"Aircraft Construction, Repair and Modification","topic":"CG Station Calculation","question":"If the CG is at 30% MAC, LEMAC is at station 1010, and MAC is 100 inches, what station is the CG?","options":["A. Station 980","B. Station 1010","C. Station 1040","D. Station 1400"],"correct_answer":"C","explanation":"CG Station = 1010 + (0.30 * 100) = Station 1040."},
  {"id":"ACRM-058","subject":"Aircraft Construction, Repair and Modification","topic":"Overload Scenario","question":"If a modern transport airplane has all passenger seats occupied, maximum baggage loaded, and full fuel tanks, the aircraft will likely:","options":["A. Exceed its certified Maximum Takeoff Weight (MTOW)","B. Be at basic operating weight","C. Be below maximum landing weight","D. Fly with negative CG"],"correct_answer":"A","explanation":"Commercial aircraft are designed with payload-fuel tradeoffs; filling both full payload and full fuel exceeds maximum allowable gross takeoff weight."},
  {"id":"ACRM-059","subject":"Aircraft Construction, Repair and Modification","topic":"Weight and Balance Sign Convention","question":"In weight and balance calculations, what determines whether an arm or moment is positive (+) or negative (-)?","options":["A. Location of weight relative to datum (aft is +, forward is -) and whether weight is added (+) or removed (-)","B. Wing camber","C. Type of scale used","D. Empty weight value"],"correct_answer":"A","explanation":"Weight added is (+), weight removed is (-); arms aft of datum are (+), arms forward of datum are (-). Moment = Weight × Arm."},
  {"id":"ACRM-060","subject":"Aircraft Construction, Repair and Modification","topic":"Useful Load Composition","question":"The useful load of a general aviation airplane consists of:","options":["A. Pilot, crew, usable fuel, usable engine oil, passengers, and cargo / baggage","B. Empty weight plus fuel","C. Aircraft frame and avionics","D. Maximum payload only"],"correct_answer":"A","explanation":"Useful load encompasses all expendable/variable load items (passengers, baggage, usable fuel, and flight crew)."},
  {"id":"ACRM-061","subject":"Aircraft Construction, Repair and Modification","topic":"LEMAC and TEMAC","question":"An aircraft's LEMAC (Leading Edge MAC) and TEMAC (Trailing Edge MAC) are specified as distances measured:","options":["A. From the reference datum line","B. From each other only","C. From the center of gravity","D. From the propeller spinner"],"correct_answer":"A","explanation":"LEMAC and TEMAC are referenced as station locations measured from the zero datum."},
  {"id":"ACRM-062","subject":"Aircraft Construction, Repair and Modification","topic":"Forward CG Loading Check","question":"When computing the critical most forward loaded CG condition, variable useful load items located aft of the forward CG limit should be loaded at:","options":["A. Minimum weight values","B. Maximum weight values","C. Zero weight","D. Average weight values"],"correct_answer":"A","explanation":"To test the extreme forward loading limit, items located aft of the forward limit are minimized (minimum fuel/empty aft seats)."},
  {"id":"ACRM-063","subject":"Aircraft Construction, Repair and Modification","topic":"Temporary / Permanent Ballast","question":"Removable dead weight (such as lead shot or sandbags) placed in an aircraft to keep the CG within allowable limits during ferry flight is:","options":["A. Tare weight","B. Temporary Ballast","C. Basic weight","D. Cargo payload"],"correct_answer":"B","explanation":"Ballast is installed to adjust the CG within certified forward and aft flight envelopes."},
  {"id":"ACRM-064","subject":"Aircraft Construction, Repair and Modification","topic":"Nose-Heavy Condition","question":"An aircraft condition where the loaded CG lies forward of the forward certified CG limit is:","options":["A. Nose-heavy (requires excessive up-elevator trim and increases stall speed)","B. Tail-heavy","C. Neutral stability","D. Dynamic roll"],"correct_answer":"A","explanation":"Loading ahead of the forward limit causes severe nose-heaviness, heavy stick forces, and difficulty flaring for landing."},
  {"id":"ACRM-065","subject":"Aircraft Construction, Repair and Modification","topic":"CG Balance Point Formula","question":"The Center of Gravity (balance point) of an aircraft is calculated using the formula:","options":["A. CG = Total Moment / Total Weight","B. CG = Total Weight / Total Moment","C. CG = Total Moment * Total Arm","D. CG = Total Weight / Span"],"correct_answer":"A","explanation":"CG = Sigma(Moments) / Sigma(Weights)."},
  {"id":"ACRM-066","subject":"Aircraft Construction, Repair and Modification","topic":"Longitudinal Balance Position","question":"To ensure natural pitch-down stall recovery and static longitudinal stability, the Center of Lift is designed to be located:","options":["A. Aft of the Center of Gravity (balanced by a downward tail force)","B. Ahead of the Center of Gravity","C. Exactly on the CG","D. At the firewall"],"correct_answer":"A","explanation":"Placing the center of lift aft of the CG creates an inherent nose-down moment, counteracted by negative tailplane lift."},
  {"id":"ACRM-067","subject":"Aircraft Construction, Repair and Modification","topic":"Tail-Heavy Condition","question":"An aircraft loaded such that its center of gravity is behind the aft certified CG limit is:","options":["A. Nose-heavy","B. Tail-heavy (dangerously unstable in pitch and susceptible to unrecoverable flat spins)","C. Highly controllable","D. Maximum range config"],"correct_answer":"B","explanation":"Aft CG beyond limits reduces or eliminates static longitudinal stability, risking uncontrollable stall/spin excursions."},
  {"id":"ACRM-068","subject":"Aircraft Construction, Repair and Modification","topic":"Zero-Fuel Weight","question":"Maximum Zero-Fuel Weight (MZFW) is the maximum permissible weight of the airplane with:","options":["A. Full payload and dry tanks (all usable fuel excluded)","B. Full fuel and no passengers","C. Minimum oil","D. Empty cabin"],"correct_answer":"A","explanation":"MZFW prevents excessive wing root bending moments by restricting the weight placed inside the fuselage prior to adding fuel in the wings."},
  {"id":"ACRM-069","subject":"Aircraft Construction, Repair and Modification","topic":"Tare Weight","question":"In aircraft weighing procedures, 'tare weight' refers to the weight of:","options":["A. Chocks, jacks, ground blocks, and shims on the scale that must be subtracted from the scale reading","B. Fuel in the tanks","C. Pilot and baggage","D. Unusable oil"],"correct_answer":"A","explanation":"Tare weight represents non-aircraft items on the scale platform that must be deducted from the gross scale reading."},
  {"id":"ACRM-070","subject":"Aircraft Construction, Repair and Modification","topic":"Weighing Fuel Drain","question":"Before weighing an aircraft for weight and balance determination, fuel tanks should be:","options":["A. Completely full","B. Drained completely with unusable fuel remaining (or subtracted from scale readings)","C. Filled to 50%","D. Pressurized"],"correct_answer":"B","explanation":"The standard method is to drain all fuel from the sump drains, leaving only the unusable fuel in the tanks."},
  {"id":"ACRM-071","subject":"Aircraft Construction, Repair and Modification","topic":"Arm Definition","question":"In weight and balance, the 'Arm' of an equipment item is defined as the:","options":["A. Horizontal distance from the reference datum plane to the center of gravity of the item","B. Vertical height from ground","C. Item weight multiplied by distance","D. Length of the item"],"correct_answer":"A","explanation":"The arm is the horizontal distance in inches from the reference datum line to the CG of the item."},
  {"id":"ACRM-072","subject":"Aircraft Construction, Repair and Modification","topic":"Datum Selection","question":"The reference datum for an aircraft is chosen by the:","options":["A. Aircraft manufacturer and specified in the Type Certificate Data Sheet (TCDS)","B. FAA inspector","C. Pilot on each flight","D. Mechanic during weighing"],"correct_answer":"A","explanation":"The datum is an imaginary vertical plane established by the aircraft designer from which all horizontal arm measurements are taken."},
  {"id":"ACRM-073","subject":"Aircraft Construction, Repair and Modification","topic":"Moment Definition","question":"An aircraft weight and balance 'Moment' is computed by:","options":["A. Multiplying the weight of an item by its horizontal arm distance from the datum (Weight × Arm)","B. Dividing weight by arm","C. Multiplying weight by density","D. Adding arm to weight"],"correct_answer":"A","explanation":"Moment = Weight × Arm (expressed in in-lbs)."},
  {"id":"ACRM-074","subject":"Aircraft Construction, Repair and Modification","topic":"Plumb Bob Leveling","question":"When leveling an aircraft using a plumb bob and leveling plate, the plumb bob line should align with the:","options":["A. Center index grid of the leveling plate","B. Firewall","C. Propeller hub","D. Main gear axle"],"correct_answer":"A","explanation":"The plumb bob suspended from an overhead point must align with the target crosshair on the leveling plate."},
  {"id":"ACRM-075","subject":"Aircraft Construction, Repair and Modification","topic":"TCDS Information","question":"Where are certified empty weight CG limits, datum location, leveling means, and maximum weights found?","options":["A. Type Certificate Data Sheet (TCDS) / Aircraft Specifications","B. Airworthiness Directive","C. Engine logbook","D. Parts Catalog"],"correct_answer":"A","explanation":"The FAA/CAAP Type Certificate Data Sheet (TCDS) contains official weight and balance limits and datum references."},

  // SECTION 3: AIRFRAME STRUCTURES, SHEET METAL & FASTENERS (ITEMS 76-100)
  {"id":"ACRM-076","subject":"Aircraft Construction, Repair and Modification","topic":"Rivet Alloy Codes","question":"An AN470AD rivet is made from which aluminum alloy?","options":["A. 2117-T4 aluminum alloy (dimpled head marking)","B. 1100 pure aluminum","C. 2024-T4 alloy","D. 7075-T6 alloy"],"correct_answer":"A","explanation":"The 'AD' code indicates 2117-T4 alloy, the most widely used field rivet, requiring no reheat treatment before driving."},
  {"id":"ACRM-077","subject":"Aircraft Construction, Repair and Modification","topic":"Rivet Pitch","question":"The spacing between adjacent rivets in the same row is known as rivet pitch, which should not be less than:","options":["A. 3D (3 times rivet shank diameter)","B. 2D","C. 1D","D. 6D"],"correct_answer":"A","explanation":"Standard rivet pitch is a minimum of 3D (commonly 4D to 6D) to prevent sheet distortion and tearing."},
  {"id":"ACRM-078","subject":"Aircraft Construction, Repair and Modification","topic":"Transverse Pitch","question":"The distance between adjacent parallel rows of rivets in a multi-row joint is the transverse pitch (gage), typically equal to:","options":["A. 75% of rivet pitch","B. 50% of rivet pitch","C. Equal to pitch","D. 2 times pitch"],"correct_answer":"A","explanation":"Transverse pitch (gage) is usually 75% of the rivet pitch between staggered rows."},
  {"id":"ACRM-079","subject":"Aircraft Construction, Repair and Modification","topic":"Dimpling vs Countersinking","question":"When installing flush 100° countersunk rivets in thin sheet metal (e.g. skin thickness less than rivet head height), the holes should be:","options":["A. Machine countersunk","B. Coin-dimpled (or hot-dimpled)","C. Reamed oversized","D. Flame cut"],"correct_answer":"B","explanation":"Machine countersinking thin skin creates knife-edge holes that tear; dimpling forms the sheet without removing metal."},
  {"id":"ACRM-080","subject":"Aircraft Construction, Repair and Modification","topic":"Rivet Gun Operation","question":"When bucking solid rivets, holding the bucking bar too lightly or bouncing off the shank results in:","options":["A. A damaged or 'clinched' shank and sheet work-hardening","B. Over-expanded shop head","C. Perfect flush seat","D. Softening of the rivet"],"correct_answer":"A","explanation":"A proper firm bucking bar rebound produces a uniform shop head without damaging the skin."},
  {"id":"ACRM-081","subject":"Aircraft Construction, Repair and Modification","topic":"Blind Fasteners","question":"CherryMAX and Huck-Clinch blind rivets are used primarily:","options":["A. In non-structural interior trim only","B. In structural applications where there is no access to the blind back-side of the structure for a bucking bar","C. In engine exhaust nozzles","D. To replace bolts in landing gear"],"correct_answer":"B","explanation":"Mechanical-lock blind rivets provide structural shear strength when the rear side is inaccessible."},
  {"id":"ACRM-082","subject":"Aircraft Construction, Repair and Modification","topic":"Sheet Metal Bend Allowance","question":"The calculation for sheet metal bend allowance is given by BA = (0.01743*R + 0.00778*T) * N. What does N represent?","options":["A. Bend radius","B. Sheet thickness","C. Number of degrees in the bend angle","D. Setback distance"],"correct_answer":"C","explanation":"N is the bend angle in degrees along the neutral axis."},
  {"id":"ACRM-083","subject":"Aircraft Construction, Repair and Modification","topic":"Neutral Axis","question":"The neutral axis in a formed piece of sheet metal is the layer where:","options":["A. Tensile stress is maximum","B. Compressive stress is maximum","C. Metal fibers neither stretch nor compress during bending","D. Cracking always begins"],"correct_answer":"C","explanation":"The neutral axis maintains its original length during plastic bending without experiencing tension or compression."},
  {"id":"ACRM-084","subject":"Aircraft Construction, Repair and Modification","topic":"Bend Radius Minimum","question":"The minimum bend radius for an aluminum alloy sheet is defined as the:","options":["A. Sharpest radius over which the metal can be bent without cracking the outer surface fibers","B. Outside radius of the bend","C. Neutral radius multiplied by 2","D. Thickness divided by 4"],"correct_answer":"A","explanation":"Bending tighter than the minimum bend radius causes severe micro-cracking on the outer tension surface."},
  {"id":"ACRM-085","subject":"Aircraft Construction, Repair and Modification","topic":"Relief Holes","question":"Relief holes drilled at the intersection of intersecting sheet metal bend lines function to:","options":["A. Relieve concentrated bending stresses and prevent tearing at the corner","B. Lighten the aircraft","C. Provide drain holes","D. Allow bolt clearance"],"correct_answer":"A","explanation":"Relief holes eliminate stress concentrations where two perpendicular bend lines intersect."},
  {"id":"ACRM-086","subject":"Aircraft Construction, Repair and Modification","topic":"Alclad Sheet","question":"Alclad 2024-T3 aluminum sheet consists of a high-strength aluminum core covered on both surfaces with:","options":["A. A thin layer of pure (99%) aluminum providing galvanic sacrificial corrosion protection","B. Anodized oxide","C. Zinc chromate primer","D. Stainless steel foil"],"correct_answer":"A","explanation":"Pure aluminum cladding is anodic to the core alloy, providing galvanic and barrier corrosion protection."},
  {"id":"ACRM-087","subject":"Aircraft Construction, Repair and Modification","topic":"Corrosion Types","question":"Filiform corrosion is characterized by:","options":["A. Worm-like or thread-like tracks of corrosion tunneling beneath the polyurethane paint film","B. Deep localized pits","C. Intergranular cracking","D. Flaking layers of metal"],"correct_answer":"A","explanation":"Filiform corrosion appears as worm-like filaments under paint films when wash primer is improperly cured or in high humidity."},
  {"id":"ACRM-088","subject":"Aircraft Construction, Repair and Modification","topic":"Intergranular Corrosion","question":"Intergranular corrosion in 2000- and 7000-series aluminum alloys is caused by:","options":["A. Improper heat treatment / slow quenching that allows precipitate segregation at grain boundaries","B. Surface scratching","C. Excess paint","D. Direct sun exposure"],"correct_answer":"A","explanation":"Slow quenching from solution heat treatment causes copper/zinc compounds to precipitate along grain boundaries, setting up galvanic micro-cells."},
  {"id":"ACRM-089","subject":"Aircraft Construction, Repair and Modification","topic":"Exfoliation Corrosion","question":"An advanced form of intergranular corrosion that delaminates and lifts surface grain layers along extrusion rolling directions is:","options":["A. Exfoliation corrosion","B. Fretting corrosion","C. Pitting corrosion","D. Galvanic corrosion"],"correct_answer":"A","explanation":"Exfoliation forces surface layers to flake or swell upward along grain boundaries."},
  {"id":"ACRM-090","subject":"Aircraft Construction, Repair and Modification","topic":"Fretting Corrosion","question":"Fretting corrosion occurs at the interface between tightly fitted structural components subjected to:","options":["A. Chemical acid contact","B. High temperature exhaust","C. Slight microscopic relative motion (vibration) under high mechanical pressure, creating fine black/cocoa powder","D. Stagnant moisture"],"correct_answer":"C","explanation":"Microscopic slip wear destroys protective oxide films, producing fine black/gray aluminum fretting debris (smoking rivets)."},
  {"id":"ACRM-091","subject":"Aircraft Construction, Repair and Modification","topic":"Control Cable Types","question":"The most flexible and widely used aircraft primary flight control cable is the:","options":["A. 7 x 19 Extra-flexible steel cable (7 strands of 19 wires each)","B. 7 x 7 Flexible cable","C. 1 x 19 Non-flexible cable","D. Solid piano wire"],"correct_answer":"A","explanation":"7x19 cable provides maximum fatigue flexibility over pulleys and around flight control quadrants."},
  {"id":"ACRM-092","subject":"Aircraft Construction, Repair and Modification","topic":"Cable Tension Compensation","question":"Automatic cable tension regulators are installed in large transport aircraft control runs to:","options":["A. Maintain constant cable tension despite thermal expansion/contraction differences between the aluminum fuselage and steel cables","B. Prevent control lockup during stalls","C. Increase pilot stick force","D. Eliminate pulleys"],"correct_answer":"A","explanation":"Aluminum fuselages expand and contract with temperature twice as much as steel cables; tension regulators compensate for this thermal differential."},
  {"id":"ACRM-093","subject":"Aircraft Construction, Repair and Modification","topic":"Cable Swaging","question":"After swaging an MS-type ball or fork terminal onto a control cable, the technician must check:","options":["A. Terminal diameter with a Go/No-Go gauge and verify the cable is visible in the inspection hole","B. Color of the fitting","C. Pulley alignment","D. Lubrication depth"],"correct_answer":"A","explanation":"A Go/No-Go gauge verifies proper terminal shank compression, and the inspection hole ensures full cable insertion depth."},
  {"id":"ACRM-094","subject":"Aircraft Construction, Repair and Modification","topic":"Turnbuckles Safetying","question":"An installed aircraft control cable turnbuckle must not expose more than how many threads outside the barrel on either end?","options":["A. 3 threads","B. 5 threads","C. 0 threads","D. 10 threads"],"correct_answer":"A","explanation":"FAA AC 43.13-1B mandates that no more than 3 threads may be visible outside the turnbuckle barrel to ensure full internal thread engagement."},
  {"id":"ACRM-095","subject":"Aircraft Construction, Repair and Modification","topic":"Self-Locking Nuts","question":"Fiber/nylon insert self-locking nuts (e.g. AN365 / MS20365) must NOT be used in:","options":["A. Locations where operating temperatures exceed 250°F or on critical rotating joints","B. Interior avionics racks","C. Fairing attachments","D. Wing root covers"],"correct_answer":"A","explanation":"Nylon locking rings degrade above 250°F and subject to rotational wear; all-metal locknuts (AN363) or castellated nuts with cotter pins must be used instead."},
  {"id":"ACRM-096","subject":"Aircraft Construction, Repair and Modification","topic":"Cotter Pin Installation","question":"When safetying an aircraft castellated nut with a cotter pin, the preferred prong bending method is:","options":["A. One prong bent up and over the bolt shank end, and the other prong bent down flat against the nut flat","B. Both prongs wrapped around the nut flats","C. Both prongs left straight","D. Prongs twisted together"],"correct_answer":"A","explanation":"The preferred method wraps one prong over the end of the bolt (cut short of diameter) and the other down against the nut flat."},
  {"id":"ACRM-097","subject":"Aircraft Construction, Repair and Modification","topic":"Safety Wiring Rules","question":"When installing double-twist safety wire (0.032\" stainless steel wire), how many twists per inch should be formed?","options":["A. 6 to 8 twists per inch","B. 2 to 4 twists per inch","C. 12 to 16 twists per inch","D. 1 twist per inch"],"correct_answer":"A","explanation":"Standard safety wiring practice requires 6 to 8 twists per inch for clean, uniform vibration resistance without over-stressing the wire."},
  {"id":"ACRM-098","subject":"Aircraft Construction, Repair and Modification","topic":"NDT Liquid Penetrant","question":"Liquid dye penetrant inspection (PT) is suitable for detecting:","options":["A. Surface-breaking cracks and discontinuities in non-porous metallic and non-metallic materials","B. Deep internal subsurface voids in thick castings","C. Magnetic flux density","D. Corrosion under paint"],"correct_answer":"A","explanation":"Dye penetrant relies on capillary action to draw liquid into surface-connected defects only."},
  {"id":"ACRM-099","subject":"Aircraft Construction, Repair and Modification","topic":"Eddy Current Testing","question":"Eddy current non-destructive testing (ET) operates based on:","options":["A. Electromagnetic induction creating circular circulating currents in conductive metals","B. High-frequency acoustic sound pulses","C. X-ray absorption","D. Capillary action"],"correct_answer":"A","explanation":"Eddy current testing induces alternating magnetic fields into conductive parts to detect surface and near-surface cracks and measure conductivity."},
  {"id":"ACRM-100","subject":"Aircraft Construction, Repair and Modification","topic":"Ultrasonic Testing","question":"Ultrasonic non-destructive testing (UT) uses high-frequency acoustic waves to detect:","options":["A. Subsurface internal flaws, laminations, and core disbonds in metallic and composite structures","B. Surface cracks only","C. Paint thickness only","D. Fuel leaks"],"correct_answer":"A","explanation":"Ultrasonic pulses travel through thick materials and reflect back from internal discontinuities and disbonds."}
);
